content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light dark;
  color: #213547;
  background-color: #f8fafc;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  justify-content: center;
  min-width: 320px;
  min-height: 100vh;
  background: linear-gradient(135deg, #f0f4f8 0%, #d9e2ec 100%);
}

* {
  box-sizing: border-box;
}

.app-container {
  width: 100%;
  max-width: 500px;
  margin: 0 auto;
  padding: 2rem;
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
}

.header {
  margin-bottom: 1.5rem;
  text-align: center;
}

.header h1 {
  font-size: 1.75rem;
  color: #1e293b;
  margin: 0;
}

.input-area {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.todo-input {
  flex: 1;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.todo-input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.btn {
  padding: 0.75rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: #3b82f6;
  color: white;
}

.btn-primary:hover {
  background-color: #2563eb;
}

.todo-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1rem;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  transition: background-color 0.2s;
}

.todo-item:hover {
  background: #f1f5f9;
}

.todo-checkbox {
  width: 1.25rem;
  height: 1.25rem;
  cursor: pointer;
  accent-color: #3b82f6;
}

.todo-text {
  flex: 1;
  margin: 0 1rem;
  font-size: 1rem;
  color: #334155;
  word-break: break-all;
}

.todo-item.completed .todo-text {
  text-decoration: line-through;
  color: #94a3b8;
}

.todo-delete {
  background-color: transparent;
  color: #ef4444;
  padding: 0.25rem 0.5rem;
  font-size: 0.875rem;
}

.todo-delete:hover {
  background-color: #fee2e2;
  color: #dc2626;
}

.empty-message {
  text-align: center;
  color: #94a3b8;
  padding: 2rem 0;
  margin: 0;
  font-size: 0.95rem;
}

export interface Todo {
  id: string;
  text: string;
  completed: boolean;
}

export interface TodoListProps {
  todos: Todo[];
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
}

export interface TodoItemProps {
  todo: Todo;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
}

import { useState, FormEvent } from 'react';
import './index.css';
import { Todo } from './types';
import TodoList from './TodoList';

export default function App() {
  const [todos, setTodos] = useState<Todo[]>([
    { id: '1', text: 'Reactのコンポーネント設計を確認する', completed: true },
    { id: '2', text: 'シンプルで使いやすいやることリストを作る', completed: false },
  ]);
  const [inputText, setInputText] = useState('');

  const handleAddTodo = (e: FormEvent) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    const newTodo: Todo = {
      id: Date.now().toString(),
      text: inputText.trim(),
      completed: false,
    };

    setTodos([newTodo, ...todos]);
    setInputText('');
  };

  const handleToggle = (id: string) => {
    setTodos(
      todos.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDelete = (id: string) => {
    setTodos(todos.filter((todo) => todo.id !== id));
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1>やることリスト</h1>
      </header>

      <form className="input-area" onSubmit={handleAddTodo}>
        <input
          type="text"
          className="todo-input"
          placeholder="新しいタスクを入力..."
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
        />
        <button type="submit" className="btn btn-primary">
          追加
        </button>
      </form>

      <TodoList todos={todos} onToggle={handleToggle} onDelete={handleDelete} />
    </div>
  );
}

import { TodoListProps } from './types';
import TodoItem from './TodoItem';

export default function TodoList({ todos = [], onToggle, onDelete }: TodoListProps) {
  if (!todos || todos.length === 0) {
    return <p className="empty-message">タスクはまだありません。新しいタスクを追加してください！</p>;
  }

  return (
    <ul className="todo-list">
      {todos.map((todo) => (
        <TodoItem
          key={todo.id}
          todo={todo}
          onToggle={onToggle}
          onDelete={onDelete}
        />
      ))}
    </ul>
  );
}

import { TodoItemProps } from './types';

export default function TodoItem({ todo, onToggle, onDelete }: TodoItemProps) {
  return (
    <li className={`todo-item ${todo.completed ? 'completed' : ''}`}>
      <input
        type="checkbox"
        className="todo-checkbox"
        checked={todo.completed}
        onChange={() => onToggle?.(todo.id)}
      />
      <span className="todo-text">{todo.text}</span>
      <button
        type="button"
        className="btn todo-delete"
        onClick={() => onDelete?.(todo.id)}
      >
        削除
      </button>
    </li>
  );
}
